import {initTracking} from './tracking.js';
import {uiQuery,uiQueryAll,initRouter} from './router.js';
import {initProgress} from './progress.js';
import {uploadState,taskPriority,isPastPersonal} from './progress-core.js';
import {initCourseWorkspace,courseWorkspaceFailed} from './course-workspace.js';
import {taskReminder} from './panel-core.js';
import {initAssistant} from './assistant.js';
import {nextSteps} from './priority-core.js';
'use strict';
initRouter();
const $=s=>uiQuery(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tz='Europe/Istanbul', dates=(value,opts={})=>new Intl.DateTimeFormat('tr-TR',{timeZone:tz,...opts}).format(new Date(value)), longDate=v=>!v?'Henüz doğrulanmadı':dates(v,/T/.test(v)?{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}:{day:'numeric',month:'short'});
const dateOf=t=>t.dueAt||t.date+'T12:00:00+03:00';
const link=(url,label)=>url?`<a class="source" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:'';
let data, view='all', boardFilter='assignments', completed={};
try{completed=JSON.parse(localStorage.getItem('kepler-completion-'+window.keplerProfile.storageId)||'{}')||{};}catch{}
const stale=v=>!v||(Date.now()-new Date(v).getTime())/36e5>data.staleAfterHours;
function badge(t){return t.verification==='unverified'?'<span class="badge amber">Doğrulanmadı</span>':t.verification==='personal'?'<span class="badge gray">Kişisel hedef</span>':`<span class="badge ${stale(t.verifiedAt)?'amber':''}">${stale(t.verifiedAt)?'Eski kontrol':'Ninova kaydı'}</span>`;}
function render(){
 const now=new Date(), today=dates(now,{year:'numeric',month:'2-digit',day:'2-digit'});
 $('#today').textContent=dates(now,{weekday:'long',day:'numeric',month:'long',year:'numeric'});
 $('#sync').classList.toggle('stale',stale(data.lastVerifiedAt));
 $('#refreshState').textContent=(data.refreshStatus==='blocked'?'Erişim engeli: son başarılı kayıt korunuyor. ':data.refreshStatus==='partial'?'Kısmi kontrol: ':data.refreshStatus==='demo'?'SENTETİK DEMO: ':!data.lastVerifiedAt?'Henüz doğrulanmadı. ':'')+(data.coverageNote||'');
 $('#sync').innerHTML=`<span>${stale(data.lastVerifiedAt)?'◷':'✓'}</span><span><b>${stale(data.lastVerifiedAt)?'Yeni kontrol gerekiyor':'Son doğrulanan görünüm'}</b> · ${esc(longDate(data.lastVerifiedAt))} İstanbul</span><small>Canlı bağlantı yok · ${data.staleAfterHours} saat sonra eski sayılır</small>`;
 const assignments=data.tasks.filter(t=>t.kind==='assignment'), upcoming=assignments.filter(t=>new Date(dateOf(t))>=now), next=upcoming.sort((a,b)=>new Date(dateOf(a))-new Date(dateOf(b)))[0], week=upcoming.filter(t=>new Date(dateOf(t))-now<=7*864e5).length;
 $('#stats').innerHTML=[['Aktif ders',data.courses.length,'Dönem boyunca birlikte','▤',''],['7 günde teslim',week,'Doğrulanmış Ninova kayıtları','↗','highlight'],['Kişisel hedef',data.tasks.filter(t=>t.kind==='personal').length,'Ninova tesliminden ayrı','◌',''],['Verisi eksik ders',data.courses.filter(c=>c.coverage==='unknown').length,'Yeni kontrol bekliyor','◷','']].map(([title,n,sub,icon,cls])=>`<div class="stat ${cls}"><div class="stat-top">${title}<span class="stat-icon">${icon}</span></div><div class="stat-value">${n}</div><small>${sub}</small></div>`).join('');
 $('#focus').innerHTML=next?`<div><div class="eyebrow">SIRADAKİ NİNOVA TESLİMİ · ${esc(next.courseId)}</div><h2>${esc(next.title)}</h2><p>${esc(next.summary)}</p><div class="focus-meta">${esc(longDate(next.dueAt))} İstanbul · ${stale(next.verifiedAt)?'Eski kontrol; kaynağı yeniden doğrula.':'Son kontrol anındaki bilgi.'}</div></div><a class="button" href="${esc(next.sourceUrl)}" target="_blank" rel="noopener noreferrer">Teslim kaynağını aç ↗</a>`:'<div><div class="eyebrow">TAKVİM DURUMU</div><h2>Yeni teslim kontrolü zamanı.</h2><p>Bu veri setinde gelecekteki Ninova teslimi görünmüyor. Güncel ödevler için Ninova’yı kontrol et.</p></div>';
 $('#courseFilter').innerHTML='<option value="all">Tüm dersler</option>'+data.courses.map(c=>`<option value="${esc(c.id)}">${esc(c.id)}</option>`).join('')+'<option value="unknown">Dersi belirsiz</option>';
 $('#feed').innerHTML=data.announcements.filter(a=>a.status!=='past_event').slice().sort((a,b)=>(b.publishedAt||'').localeCompare(a.publishedAt||'')).map(a=>`<article class="feed-item"><div class="task-top"><span class="course-tag">${esc(a.courseId)}</span><span class="badge gray">${a.status==='actionable_blocker'?'Kaynak sorunu':'Duyuru'}</span></div><h3>${esc(a.title)}</h3><details class="notice-expand"><summary>Duyuru metnini oku</summary><p>${esc(a.body)}</p></details>${link(a.sourceUrl,'Ninova kaynağı')} ${link(a.resourceUrl,'Dosya klasörü')} ${link(a.locationUrl,'Buluşma konumu')}<small>${a.publishedAt?'Yayın: '+esc(longDate(a.publishedAt))+' · ':''}Kontrol: ${esc(longDate(a.verifiedAt))} · ${stale(a.verifiedAt)?'Eski kontrol':a.publishedAt&&/T/.test(a.publishedAt)?'Son kontrol anındaki kayıt':'Yayın saati bilinmiyor'}</small></article>`).join('');
 $('#scheduleNote').innerHTML=data.scheduleNotes.map(n=>`<p>${esc(n)}</p>`).join('');
 renderTasks();
 renderPriorities();
 renderSecondary();
 $('#briefStatus').textContent='Ninova kontrolü: '+longDate(data.lastVerifiedAt)+(stale(data.lastVerifiedAt)?' · eski kayıt.':' · anlık veri kopyası.');
}
function renderTasks(){
 const course=$('#courseFilter').value,q=$('#search').value.trim().toLocaleLowerCase('tr-TR');
 const tasks=data.tasks.filter(t=>!isPast(t)).filter(t=>(course==='all'||(course==='unknown'?!t.courseId:t.courseId===course))&&(view==='all'||(view==='verified'?t.kind==='assignment':t.kind==='personal'))&&[t.title,t.courseId,t.courseLabel,t.summary].join(' ').toLocaleLowerCase('tr-TR').includes(q)).sort((a,b)=>new Date(dateOf(a))-new Date(dateOf(b)));
 $('#resultCount').textContent=tasks.length+' kayıt';$('#empty').hidden=tasks.length>0;
 $('#taskList').innerHTML=tasks.map(t=>{const d=dateOf(t),s=t.submission,past=t.dueAt?new Date(t.dueAt)<new Date():t.date<new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());return `<article class="task ${completed[t.id]?'local-done':''}"><div class="datebox"><strong>${dates(d,{day:'numeric'})}</strong><span>${dates(d,{month:'short'}).toLocaleUpperCase('tr-TR')}</span></div><div><div class="task-top"><span class="course-tag">${esc(t.courseId||t.courseLabel)}</span>${badge(t)}${past?'<span class="badge amber">Tarih geçti · durum kontrolü gerek</span>':''}</div><h3>${esc(t.title)}</h3><p class="task-desc">${esc(t.summary)}</p><div class="task-foot"><span>◷ ${t.dueAt?dates(d,{hour:'2-digit',minute:'2-digit'})+' · İstanbul':'Saat belirtilmedi'}</span>${link(t.sourceUrl,'Ninova kaynağı')}${t.kind==='milestone'?'<span class="badge gray">Ders dönüm noktası</span>':''}</div>${s?`<details><summary>Ninova durumu & teslim içeriği</summary><p>Kendi hesabın: ${s.ownUploaded}/${s.expectedFiles} dosya · ${esc(longDate(t.verifiedAt))} kontrolü${s.scope==='group'?'<br><b>Grup durumu bilinmiyor. Bir üye teslim eder; kendi 0 kaydın grup başarısızlığı değildir.</b>':''}</p>${t.requirements.map(r=>`<p>• ${esc(r)}</p>`).join('')}</details>`:''}${(t.resources||[]).length?`<div class="task-resources">${t.resources.map(r=>link(r.url,r.title)).join(' ')}</div>`:''}${t.verifiedAt?`<div class="local-note">Son doğrulama: ${esc(longDate(t.verifiedAt))}${stale(t.verifiedAt)?' · Eski kontrol':''}</div>`:'<div class="local-note">Ninova doğrulaması yok · kullanıcı notu</div>'}<label class="check"><input type="checkbox" data-task="${esc(t.id)}" ${completed[t.id]?'checked':''}><span>Kendi planımda tamamladım</span></label><div class="local-note">Yalnızca bu tarayıcıda · Ninova teslim durumunu değiştirmez.</div></div></article>`;}).join('');
}
function renderPriorities(){
 const tasks=data.tasks.filter(t=>boardFilter==='all'||!isPastPersonal(t)).filter(t=>boardFilter!=='assignments'||!completed[t.id]&&!(t.submission&&uploadState(t.submission).ownComplete)).filter(t=>boardFilter==='all'||(boardFilter==='assignments'?t.kind==='assignment':t.kind!=='assignment')).sort((a,b)=>Number(!!completed[a.id])-Number(!!completed[b.id])||taskPriority(b,new Date(),data.staleAfterHours).rank-taskPriority(a,new Date(),data.staleAfterHours).rank||new Date(dateOf(a))-new Date(dateOf(b)));
 const now=new Date(),pending=tasks.filter(t=>!completed[t.id]),near=pending.filter(t=>['urgent','soon'].includes(taskReminder(t,now).tone));
 $('#assignmentReminder').textContent=near.length?`${near.length} yakın tarihli işin var. Önce en yakın teslimi kontrol et.`:pending.length?`${pending.length} hazırlık kaydı bekliyor. Tarihler son kontrol kopyasına aittir.`:'Bu görünümdeki hazırlık işaretlerin tamam. Ninova teslimlerini ayrıca doğrula.';
 $('#priorityList').innerHTML=tasks.length?tasks.map(t=>{const reminder=taskReminder(t,now),priority=taskPriority(t,now,data.staleAfterHours),done=!!completed[t.id],date=dateOf(t),s=t.submission;return `<article class="assignment-card reminder-${reminder.tone} priority-${priority.tone} ${done?'plan-ready':''}" data-assignment-id="${esc(t.id)}"><div class="assignment-top"><span class="course-tag">${esc(t.courseId||t.courseLabel||'Dersi belirsiz')}</span><span class="deadline-cue">${esc(priority.label)}</span></div><h3>${esc(t.title)}</h3><div class="assignment-due"><span>${t.dueAt?'Son teslim':'Hedef tarih'}</span><strong>${esc(dates(date,{day:'numeric',month:'long',weekday:'short'}))}</strong><b>${t.dueAt?esc(dates(date,{hour:'2-digit',minute:'2-digit'}))+' · İstanbul':'Saat bilinmiyor'}</b></div><div class="assignment-status">${badge(t)}${s?`<span>Kendi hesabın: ${s.ownUploaded}/${s.expectedFiles} dosya</span>`:''}</div>${s?.scope==='group'?'<p class="group-caveat">Bir grup üyesinin yüklemesi yeterli. Kendi 0 kaydın grubun teslim etmediği anlamına gelmez; grup sonucu bilinmiyor.</p>':''}<div class="assignment-actions">${link(t.sourceUrl,'Ödev kaynağını aç')}${(t.resources||[]).map(r=>link(r.url,r.title)).join(' ')}</div><details class="assignment-details"><summary>Teslim içeriği ve kaynak ayrıntıları</summary><p>${esc(reminder.detail)}</p><p>${esc(nextSteps[t.id]||t.summary)}</p><p>${esc(t.summary)}</p>${(t.requirements||[]).length?`<ul>${t.requirements.map(r=>`<li>${esc(r)}</li>`).join('')}</ul>`:''}</details><div class="assignment-check"><label><input type="checkbox" data-task="${esc(t.id)}" ${done?'checked':''} aria-label="${esc(t.title+': kendi planımda tamamlandı')}"><span>${done?'Kendi planımda hazır':'Kendi planımda hazır olarak işaretle'}</span></label><small>Ninova teslim durumundan ayrı · Bu tarayıcıda</small></div><small class="assignment-verified">${t.verifiedAt?'Kaynak kontrolü: '+esc(longDate(t.verifiedAt))+(stale(t.verifiedAt)?' · Eski kontrol':''):'Ninova’da doğrulanmadı; kişisel not'}</small></article>`}).join(''):'<p class="priority-empty">Bu görünümde aktarılmış iş yok. Eksik bilgi, yeni ödev olmadığı anlamına gelmez.</p>';
}
function isPast(t){return t.dueAt?new Date(t.dueAt)<new Date():t.date<new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function renderSecondary(){
 const row=(course,title,date,time,body,url)=>`<article class="compact-row"><span class="compact-date">${esc(dates(date+'T12:00:00+03:00',{day:'numeric',month:'short'}))}${time?'<br>'+esc(time):''}</span><div><span class="course-tag">${esc(course)}</span><h3>${esc(title)}</h3><p>${esc(body)}</p>${link(url,'Kaynak')}</div></article>`;
 $('#futureList').innerHTML=(data.futureMilestones||[]).slice().sort((a,b)=>a.date.localeCompare(b.date)).map(m=>row(m.courseId,m.title,m.date,m.time,'İzlence hedefi · '+(m.checkedAt?'Kaynak kontrolü: '+longDate(m.checkedAt):'Son kontrol tarihi aktarılmadı')+' · Yeni duyuruyla yeniden doğrula.',m.sourceUrl)).join('');
 $('#historyList').innerHTML=(data.history||[]).map(h=>row(h.courseId,h.title,h.date,h.time,'Tarih geçti; teslim sonucu bilinmiyor. '+h.basis,h.sourceUrl)).join('')+data.tasks.filter(isPast).map(t=>row(t.courseId||t.courseLabel,t.title,t.date||t.dueAt.slice(0,10),null,'Tarih geçti. Güncel teslim sonucu bilinmiyor; eski yükleme sayısı sonuç kanıtı değildir.',t.sourceUrl)).join('')+data.announcements.filter(a=>a.status==='past_event').map(a=>row(a.courseId,a.title,a.publishedAt.slice(0,10),null,a.body,a.sourceUrl)).join('');
}
$('#search').addEventListener('input',()=>data&&renderTasks());$('#courseFilter').addEventListener('change',()=>data&&renderTasks());
uiQueryAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;uiQueryAll('[data-view]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b?'true':'false')});if(data)renderTasks()}));
document.addEventListener('change',e=>{if(!e.target.dataset.task)return;completed[e.target.dataset.task]=e.target.checked;let saved=true;try{localStorage.setItem('kepler-completion-'+window.keplerProfile.storageId,JSON.stringify(completed))}catch{saved=false}renderTasks();renderPriorities();document.dispatchEvent(new CustomEvent('kepler:plan-changed'));$('#toast').textContent=saved?'Kişisel planın güncellendi. Ninova durumu değişmedi.':'Bu tarayıcı kaydetmeye izin vermedi; işaret yalnızca bu oturumda.';$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)});
fetch('school-data.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.json()}).then(d=>{data=d;render();initAssistant(data,()=>completed);initCourseWorkspace(data,()=>completed);initProgress(data,()=>completed);initTracking(data);window.keplerReady=true}).catch(()=>{$('#sync').textContent='Veri dosyası yüklenemedi. Sayfayı yenile veya Ninova kaynağını kontrol et.';$('#sync').classList.add('stale');courseWorkspaceFailed()});

// Open the requested detail before anchor navigation, including keyboard activation.
document.addEventListener('click',e=>{const a=e.target.closest('[data-open-panel]');if(a){const panel=uiQuery('#'+a.dataset.openPanel);if(panel)panel.open=true;}});

uiQueryAll('[data-board-filter]').forEach(b=>b.addEventListener('click',()=>{boardFilter=b.dataset.boardFilter;uiQueryAll('[data-board-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));if(data)renderPriorities()}));
